import os

import pytest
from conftest import run

BOM = b"\xef\xbb\xbf"


def stat(tmp_path, data, *args):
    f = tmp_path / "in.txt"
    f.write_bytes(data)
    p = run(*args, str(f))
    assert p.returncode == 0
    assert p.stderr == b""
    return p.stdout


def test_empty_text(tmp_path):
    assert stat(tmp_path, b"") == b"lines: 0\nwords: 0\nchars: 0\ntop:\n"


def test_empty_json(tmp_path):
    assert stat(tmp_path, b"", "--json") == (
        b'{"lines": 0, "words": 0, "chars": 0, "top": []}\n'
    )


def test_bom_only(tmp_path):
    assert stat(tmp_path, BOM) == b"lines: 0\nwords: 0\nchars: 0\ntop:\n"


def test_bom_excluded_from_chars(tmp_path):
    assert stat(tmp_path, BOM + b"ab\n") == b"lines: 1\nwords: 1\nchars: 3\ntop: ab=1\n"


def test_double_bom_counts_one_char(tmp_path):
    assert stat(tmp_path, BOM + BOM) == b"lines: 1\nwords: 0\nchars: 1\ntop:\n"


def test_crlf(tmp_path):
    assert stat(tmp_path, b"\r\n") == b"lines: 1\nwords: 0\nchars: 2\ntop:\n"


def test_lone_cr(tmp_path):
    assert stat(tmp_path, b"a\rb") == b"lines: 2\nwords: 2\nchars: 3\ntop: a=1 b=1\n"


def test_no_trailing_newline(tmp_path):
    assert stat(tmp_path, b"hi there") == (
        b"lines: 1\nwords: 2\nchars: 8\ntop: hi=1 there=1\n"
    )


def test_digits(tmp_path):
    assert stat(tmp_path, b"a1 42 B2") == (
        b"lines: 1\nwords: 3\nchars: 8\ntop: 42=1 a1=1 b2=1\n"
    )


def test_apostrophe_splits(tmp_path):
    assert stat(tmp_path, b"don't") == b"lines: 1\nwords: 2\nchars: 5\ntop: don=1 t=1\n"


def test_ties_sorted_by_word(tmp_path):
    out = stat(tmp_path, b"b a c b a c d", "--top", "4")
    assert out.endswith(b"top: a=2 b=2 c=2 d=1\n")


def test_top_larger_than_distinct(tmp_path):
    out = stat(tmp_path, b"x y x", "--top", "10")
    assert out.endswith(b"top: x=2 y=1\n")


def test_very_large_top(tmp_path):
    out = stat(tmp_path, b"x y x", "--top", "99999999999999999999")
    assert out.endswith(b"top: x=2 y=1\n")


def test_top_equals_form(tmp_path):
    out = stat(tmp_path, b"x y x z", "--top=2")
    assert out.endswith(b"top: x=2 y=1\n")


def test_options_after_file(tmp_path):
    f = tmp_path / "in.txt"
    f.write_bytes(b"x y x")
    p = run(str(f), "--json", "--top", "1")
    assert p.returncode == 0
    assert p.stdout == (
        b'{"lines": 1, "words": 3, "chars": 5, "top": [{"word": "x", "count": 2}]}\n'
    )


def test_non_ascii_is_not_a_word(tmp_path):
    out = stat(tmp_path, "café ab".encode("utf-8"))
    assert out == b"lines: 1\nwords: 3\nchars: 7\ntop: ab=1 caf=1\n"


def test_determinism_under_hostile_env(tmp_path):
    f = tmp_path / "in.txt"
    f.write_bytes(BOM + "café a\r\nb a\r\n".encode("utf-8"))
    env = dict(os.environ, LC_ALL="C", PYTHONIOENCODING="ascii", PYTHONUTF8="0")
    for args in ((), ("--json",)):
        base = run(*args, str(f))
        hostile = run(*args, str(f), env=env)
        assert base.returncode == hostile.returncode == 0
        assert hostile.stdout == base.stdout
        assert hostile.stderr == base.stderr == b""
        assert b"\r" not in hostile.stdout

